  }

  .frame{
    position:relative; z-index:1;
    max-width:1440px; margin:0 auto; min-height:100dvh;
    padding:16px 20px 10px;
    display:grid; grid-template-rows:auto 1fr auto auto; gap:12px;
  }

  /* ---------- header ---------- */
  header{display:flex; justify-content:space-between; align-items:flex-end; gap:16px; flex-wrap:wrap; padding:2px 2px 0}
  .brand h1{
    font:700 clamp(21px,2.6vw,29px)/1 var(--mono);
