  .meter{height:3px; background:#17202b; border-radius:2px; overflow:hidden}
  .meter i{display:block; height:100%; width:0; background:linear-gradient(90deg,var(--teal),var(--green)); transition:width .25s}

  .controls{display:flex; align-items:center; gap:16px; flex-wrap:wrap}
  .btns{display:flex; gap:8px}
  button{
    font:700 12px/1 var(--mono); letter-spacing:.1em; text-transform:uppercase;
    padding:11px 16px; border-radius:8px; cursor:pointer;
    background:#1a222c; color:#dfe9f2; border:1px solid var(--line2);
    transition:transform .12s, box-shadow .15s, border-color .15s, background .2s;
  }
  button:hover{transform:translateY(-1px); border-color:rgba(57,208,216,.55); box-shadow:0 5px 16px rgba(0,0,0,.45), 0 0 0 1px rgba(57,208,216,.2)}
