  button:focus-visible{outline:2px solid var(--teal); outline-offset:2px}
  #sort{min-width:122px; background:linear-gradient(180deg,#ffcf87,#ff9d3c); border-color:#c97a26; color:#2b1602; text-shadow:0 1px 0 rgba(255,255,255,.25)}
  #sort:hover{border-color:var(--amber); box-shadow:0 6px 18px rgba(255,157,60,.3), 0 0 0 1px rgba(255,180,84,.4)}
  #sort.on{background:linear-gradient(180deg,#ff8fa0,#ff5d73); border-color:#c23a52; color:#2b040b; text-shadow:none}
  #sort.on:hover{box-shadow:0 6px 18px rgba(255,93,115,.3), 0 0 0 1px rgba(255,93,115,.4)}

  .field{display:flex; align-items:center; gap:9px; font:600 10px/1 var(--sans); letter-spacing:.18em; text-transform:uppercase; color:var(--dim)}
  select{
    appearance:none; -webkit-appearance:none;
    background-color:#161d26; border:1px solid var(--line2); color:#cfe0ec;
    font:600 12px var(--mono); letter-spacing:.05em;
    padding:9px 30px 9px 11px; border-radius:7px; cursor:pointer;
    background-image:linear-gradient(45deg,transparent 50%,#7c8b9c 50%),linear-gradient(135deg,#7c8b9c 50%,transparent 50%);
    background-position:calc(100% - 17px) 55%, calc(100% - 12px) 55%;
    background-size:5px 5px; background-repeat:no-repeat;
    transition:border-color .15s;
  }
  select:hover{border-color:rgba(57,208,216,.5)}
  select option{background:#10161d}
  input[type=range]{accent-color:var(--teal); width:130px; cursor:pointer}
  .field output{font:700 12px var(--mono); color:#cfe0ec; min-width:38px; font-variant-numeric:tabular-nums}

  footer{display:flex; justify-content:space-between; gap:12px; flex-wrap:wrap; font:11px var(--mono); color:var(--faint); padding:0 2px 4px}
  kbd{font:10px var(--mono); border:1px solid var(--line2); border-bottom-width:2px; border-radius:4px; padding:2px 5px; background:#161d26; color:#aebdc9}
  .api b{color:var(--teal); font-weight:600}
  .api i{width:6px;height:6px;border-radius:50%;background:var(--green);display:inline-block;margin-right:6px;box-shadow:0 0 6px rgba(89,223,142,.8)}

  @media (max-width:760px){
    .ro.opt{display:none}
    .stat{padding-right:16px;margin-right:16px}
    .stat b{font-size:16px}
  }
  @media (prefers-reduced-motion:reduce){
    #stage::after,.led{animation:none}
    .bar.wave{animation:none}
    .bar{transition:none}
  }
</style>
