<body>
<div class="frame">

  <header>
    <div class="brand">
      <h1>ARRAY<span>SCOPE</span></h1>
      <p>comparison-sort instrument</p>
    </div>
    <div class="readouts">
      <div class="ro"><label>Status</label><b><i id="led" class="led idle"></i><span id="statusTxt">IDLE</span></b></div>
      <div class="ro"><label>Algorithm</label><b id="algoRo">QUICKSORT</b></div>
      <div class="ro opt"><label>Complexity</label><b id="cplxRo">O(n log n) avg</b></div>
      <div class="ro"><label>n</label><b id="nRo">0</b></div>
    </div>
  </header>

  <main id="stage">
    <div id="algoTag">quicksort</div>
    <div id="probe">▸ ready</div>
    <div id="bars" aria-label="array bars"></div>
  </main>

  <section id="deck">
    <div>
      <div class="stats">
        <div class="stat"><label>Steps</label><b id="stSteps">0</b></div>
        <div class="stat"><label>Comparisons</label><b id="stCmp">0</b></div>
        <div class="stat"><label>Writes</label><b id="stWr">0</b></div>
        <div class="stat"><label>Locked</label><b id="stLock">0<small>/0</small></b></div>
      </div>
      <div class="meter"><i id="meterFill"></i></div>
    </div>
    <div class="controls">
      <div class="btns">
        <button id="sort" title="Animate the sort to completion">▶ sort</button>
        <button id="shuffle" title="Randomize the array">⌁ shuffle</button>
        <button id="reset" title="Restore the starting array">↺ reset</button>
      </div>
      <label class="field">Algorithm
        <select id="algo">
          <option value="bubble">Bubble</option>
          <option value="selection">Selection</option>
          <option value="insertion">Insertion</option>
          <option value="merge">Merge</option>
          <option value="quick" selected>Quicksort</option>
          <option value="heap">Heapsort</option>
        </select>
      </label>
      <label class="field">Speed
        <input type="range" id="speed" min="1" max="100" value="42">
        <output id="speedVal">×26</output>
      </label>
      <label class="field">Size
        <input type="range" id="size" min="8" max="140" value="48">
        <output id="sizeVal">48</output>
      </label>
    </div>
  </section>

  <footer>
    <span><kbd>space</kbd> sort/pause &nbsp; <kbd>S</kbd> shuffle &nbsp; <kbd>R</kbd> reset &nbsp; <kbd>1</kbd>–<kbd>6</kbd> algorithm</span>
    <span class="api"><i></i>window.viz — <b>array()</b> · <b>setArray()</b> · <b>sortStep()</b> · <b>sorted()</b></span>
  </footer>

</div>

<script>
(() => {
  "use strict";

  /* ---------------- state ---------------- */
  let arr = [];
  let baseline = [];
  let barsEls = [];
  let gen = null;              // active sort generator
  let running = false;         // animation loop active
  let announced = false;       // "sorted" fanfare already played
  let locked = new Set();      // indices confirmed in final position
  let hotIdx = [];             // temporarily highlighted indices
  let steps = 0, comparisons = 0, writes = 0;
  let minV = 0, maxV = 0, rangeV = 1;
  let probeTxt = "ready";

  /* ---------------- dom ---------------- */
  const $ = id => document.getElementById(id);
  const barsEl = $("bars"), stageEl = $("stage"),
        sortBtn = $("sort"), shuffleBtn = $("shuffle"), resetBtn = $("reset"),
        algoSel = $("algo"), speedEl = $("speed"), sizeEl = $("size"),
        speedVal = $("speedVal"), sizeVal = $("sizeVal"),
        ledEl = $("led"), statusTxt = $("statusTxt"),
        algoRo = $("algoRo"), cplxRo = $("cplxRo"), nRo = $("nRo"),
        stSteps = $("stSteps"), stCmp = $("stCmp"), stWr = $("stWr"),
        stLock = $("stLock"), meterFill = $("meterFill"),
        probeEl = $("probe"), algoTag = $("algoTag");

  /* ---------------- helpers ---------------- */
  const sw = (a, i, j) => { const t = a[i]; a[i] = a[j]; a[j] = t; };

  function isSorted(a){
    for (let i = 1; i < a.length; i++) if (a[i-1] > a[i]) return false;
    return true;
  }

  function shuffled(n){
    const a = Array.from({length:n}, (_, i) => i + 1);
    for (let i = n - 1; i > 0; i--){
      const j = Math.floor(Math.random() * (i + 1));
      const t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  /* ---------------- sorting generators ----------------
     Each yield === exactly one atomic step (comparison / write / lock).
     The array is mutated in place before the describing op is yielded. */

  function* bubble(a){
    const n = a.length;
    for (let end = n - 1; end > 0; end--){
      let swapped = false;
      for (let j = 0; j < end; j++){
        yield {t:"cmp", i:j, j:j+1};
        if (a[j] > a[j+1]){ sw(a, j, j+1); swapped = true; yield {t:"swp", i:j, j:j+1}; }
      }
      yield {t:"lock", i:end};
      if (!swapped){ for (let k = 0; k < end; k++) yield {t:"lock", i:k}; return; }
    }
    if (n > 0) yield {t:"lock", i:0};
  }

  function* selection(a){
    const n = a.length;
    for (let i = 0; i < n - 1; i++){
      let m = i;
      for (let j = i + 1; j < n; j++){
        yield {t:"cmp", i:m, j:j};
        if (a[j] < a[m]) m = j;
      }
      if (m !== i){ sw(a, i, m); yield {t:"swp", i:i, j:m}; }
      yield {t:"lock", i:i};
    }
    if (n > 1) yield {t:"lock", i:n-1};
  }

  function* insertion(a){
    for (let i = 1; i < a.length; i++){
      for (let j = i; j > 0; j--){
        yield {t:"cmp", i:j-1, j:j};
        if (a[j-1] > a[j]){ sw(a, j-1, j); yield {t:"swp", i:j-1, j:j}; }
        else break;
      }
    }
  }

  function* mergeRec(a, lo, hi){
    if (lo >= hi) return;
    const mid = (lo + hi) >> 1;
    yield* mergeRec(a, lo, mid);
    yield* mergeRec(a, mid + 1, hi);
    const L = a.slice(lo, mid + 1), R = a.slice(mid + 1, hi + 1);
    let i = 0, j = 0, k = lo;
    while (i < L.length && j < R.length){
      yield {t:"cmp", i:k, j:mid + 1 + j};
      if (L[i] <= R[j]) a[k] = L[i++]; else a[k] = R[j++];
      yield {t:"set", i:k};
      k++;
    }
    while (i < L.length){ a[k] = L[i++]; yield {t:"set", i:k}; k++; }
    while (j < R.length){ a[k] = R[j++]; yield {t:"set", i:k}; k++; }
  }
  function* merge(a){ yield* mergeRec(a, 0, a.length - 1); }

  function* qs(a, lo, hi){
    while (lo < hi){
      const mid = (lo + hi) >> 1;
      // median-of-three pivot guard (avoids O(n^2) on pre-sorted input)
      yield {t:"cmp", i:lo, j:mid}; if (a[lo] > a[mid]){ sw(a, lo, mid); yield {t:"swp", i:lo, j:mid}; }
      yield {t:"cmp", i:lo, j:hi};  if (a[lo] > a[hi]) { sw(a, lo, hi);  yield {t:"swp", i:lo, j:hi}; }
      yield {t:"cmp", i:mid, j:hi}; if (a[mid] > a[hi]){ sw(a, mid, hi); yield {t:"swp", i:mid, j:hi}; }
      sw(a, mid, hi); yield {t:"swp", i:mid, j:hi};
      const pivot = a[hi];
      let p = lo;
      for (let j = lo; j < hi; j++){
        yield {t:"cmp", i:j, j:hi};
        if (a[j] < pivot){ if (p !== j){ sw(a, p, j); yield {t:"swp", i:p, j:j}; } p++; }
      }
      sw(a, p, hi); yield {t:"swp", i:p, j:hi};
      yield {t:"lock", i:p};
      if (p - lo < hi - p){ yield* qs(a, lo, p - 1); lo = p + 1; }
      else                { yield* qs(a, p + 1, hi); hi = p - 1; }
    }
    if (lo === hi) yield {t:"lock", i:lo};
  }
  function* quick(a){ yield* qs(a, 0, a.length - 1); }

  function* heap(a){
    const n = a.length;
    function* sift(i, size){
      for (;;){
        const l = 2*i + 1, r = l + 1; let m = i;
        if (l < size){ yield {t:"cmp", i:l, j:m}; if (a[l] > a[m]) m = l; }
        if (r < size){ yield {t:"cmp", i:r, j:m}; if (a[r] > a[m]) m = r; }
        if (m === i) return;
        sw(a, i, m); yield {t:"swp", i:i, j:m};
        i = m;
      }
    }
    for (let i = (n >> 1) - 1; i >= 0; i--) yield* sift(i, n);
    for (let end = n - 1; end > 0; end--){
      sw(a, 0, end); yield {t:"swp", i:0, j:end};
      yield {t:"lock", i:end};
      yield* sift(0, end);
    }
    if (n > 0) yield {t:"lock", i:0};
  }

  const ALGOS = {
    bubble:   {name:"Bubble sort",    cplx:"O(n²) · O(1)",       fn:bubble},
    selection:{name:"Selection sort", cplx:"O(n²) · O(1)",       fn:selection},
    insertion:{name:"Insertion sort", cplx:"O(n²) · O(1)",       fn:insertion},
    merge:    {name:"Merge sort",     cplx:"O(n log n) · O(n)",  fn:merge},
    quick:    {name:"Quicksort",      cplx:"O(n log n) avg",     fn:quick},
    heap:     {name:"Heapsort",       cplx:"O(n log n) · O(1)",  fn:heap},
  };
  const algoKey = () => algoSel.value;

  /* ---------------- rendering ---------------- */
  function computeRange(){
    minV = Infinity; maxV = -Infinity;
    for (const v of arr){ if (v < minV) minV = v; if (v > maxV) maxV = v; }
    if (!arr.length){ minV = 0; maxV = 1; }
    rangeV = (maxV - minV) || 1;
  }

  function heightPct(v){
    if (maxV === minV) return 88;
    if (minV >= 0) return Math.max(2.5, (v / maxV) * 100);
    return 5 + ((v - minV) / rangeV) * 95;
  }

  function barColor(v){
    const t = maxV === minV ? .5 : (v - minV) / rangeV;
    const h = 205 - 165 * t;               // steel-blue → amber-gold
    return `hsl(${h.toFixed(1)} ${(70 + 14*t).toFixed(0)}% ${(45 + 13*t).toFixed(0)}%)`;
  }

  function paint(i){
    const el = barsEls[i]; if (!el) return;
    el.style.height = heightPct(arr[i]) + "%";
    el.style.backgroundColor = barColor(arr[i]);
  }

  function rebuild(){
    hotIdx.length = 0; locked.clear();
    barsEl.innerHTML = ""; barsEls = [];
    for (let i = 0; i < arr.length; i++){
      const d = document.createElement("div");
      d.className = "bar";
      barsEl.appendChild(d);
      barsEls.push(d);
    }
    computeRange();
    for (let i = 0; i < arr.length; i++) paint(i);
    // entrance ripple
    const dly = Math.min(8, 320 / Math.max(1, arr.length));
    barsEls.forEach((el, i) => { el.style.animationDelay = (i * dly) + "ms"; el.classList.add("enter"); });
    setTimeout(() => barsEls.forEach(el => { el.classList.remove("enter"); el.style.animationDelay = ""; }),
               arr.length * dly + 600);
    nRo.textContent = arr.length;
  }

  function clearHot(){
    for (const i of hotIdx){ const el = barsEls[i]; if (el) el.classList.remove("cmp", "swp"); }
    hotIdx.length = 0;
  }
  function hot(i, j, cls){
    for (const k of (j == null ? [i] : [i, j])){
      const el = barsEls[k];
      if (el){ el.classList.add(cls); hotIdx.push(k); }
    }
  }

  function applyOp(op){
    clearHot();
    if (op.t === "cmp"){
      comparisons++; hot(op.i, op.j, "cmp");
      probeTxt = `cmp a[${op.i}] ↔ a[${op.j}]`;
    } else if (op.t === "swp"){
      writes++; paint(op.i); paint(op.j); hot(op.i, op.j, "swp");
      probeTxt = `swap a[${op.i}] ↔ a[${op.j}]`;
    } else if (op.t === "set"){
      writes++; paint(op.i); hot(op.i, null, "swp");
      probeTxt = `write a[${op.i}] ← ${arr[op.i]}`;
    } else if (op.t === "lock"){
      locked.add(op.i);
      const el = barsEls[op.i]; if (el) el.classList.add("done");
      probeTxt = `lock a[${op.i}]`;
    }
  }

  /* ---------------- stats / status ---------------- */
